def exclusiveTimes(n, logs):
    res = [0] * n
    stack = []
    prev = 0
    for fid, kind, t in logs:
        if kind == 0:
            if stack:
                res[stack[-1]] += t - prev
            stack.append(fid)
            prev = t
        else:
            res[stack.pop()] += t + 1 - prev
            prev = t + 1
    return res
